update_rule.pseudocode:
for each day d:
  if d mod round(7 / messaging_frequency_per_week) == 0:
    for each person i:
      info_signal = 0
      for each media source m:
        exposure = Bernoulli(communication_reach * m.reach)
        if exposure == 1:
          content_effect = messaging_effect_size * (m.credibility * (m.bias in {pro_public_health, neutral}? 1 : -1))
          misinformation_effect = - messaging_effect_size * misinformation_rate * (1 - i.trust_media)
          info_signal += content_effect + misinformation_effect
      ph_exposure = Bernoulli(communication_reach)
      if ph_exposure == 1:
        info_signal += messaging_effect_size * i.trust_public_health
        i.policy_awareness = min(1.0, i.policy_awareness + policy_awareness_increment)
      # update risk perception with decay
      i.risk_perception = clamp( (1 - info_decay_rate) * i.risk_perception + info_signal, 0, 1 )
      # modest trust updates
      i.trust_public_health = clamp(i.trust_public_health + trust_update_scale * messaging_effect_size - misinformation_rate * 0.05, 0, 1)
      i.trust_media = clamp(i.trust_media + 0.02 * (abs(info_signal) < 0.01 ? -1 : 1), 0, 1)
  emit signal.information_effects for modules needing it

policy_active = (time.day >= policy_mandate_day)
for each venue entry attempt (person i):
  if policy_active and (i.mask_use == 0):
    enforced = Bernoulli(enforcement_level)
    if enforced:
      if Bernoulli(denial_probability_without_mask):
        record denied entry event
      else:
        issue fine with probability enforcement_level; record fine event

new_infections = 0
for each contact (i,j):
  if health_status(i) == I and health_status(j) == S or vice versa:
    m_eff = 1 - (1 - mask_efficacy)^(mask_use_i + mask_use_j)  # both wearing reduces risk multiplicatively
    p_trans = baseline_transmission_prob * (1 - m_eff)
    if Bernoulli(p_trans):
      infect the S individual; new_infections += 1
# Recovery
for each infected k:
  if days_since_infection >= disease_recovery_days_mean:
    health_status(k) = R
record infections_daily = new_infections
# Counterfactual no-mask infections (for averted cases)
compute same contacts with mask_efficacy = 0 to record infections_nomask_daily
